from itertools import product

P_rain = {True: 0.2, False: 0.8}
P_sprk = {True: 0.3, False: 0.7}
# P(wet | rain, sprinkler). One number per parent combination.
P_wet = {(True, True): 0.99, (True, False): 0.9,
         (False, True): 0.8, (False, False): 0.05}

def joint(r, s, w):                  # multiply the local tables.
    pw = P_wet[(r, s)]
    return P_rain[r] * P_sprk[s] * (pw if w else 1 - pw)

def prob(query, given):              # enumerate matching worlds.
    num = den = 0.0
    for r, s, w in product([True, False], repeat=3):
        world = {"rain": r, "sprinkler": s, "wet": w}
        if all(world[k] == v for k, v in given.items()):
            p = joint(r, s, w)
            den += p                     # all worlds matching the evidence.
            if all(world[k] == v for k, v in query.items()):
                num += p
    return round(num / den, 2)       # normalise.

print(prob({"sprinkler": True}, {}))                         # 0.3
print(prob({"sprinkler": True}, {"wet": True}))             # 0.62
print(prob({"sprinkler": True}, {"wet": True, "rain": True}))  # 0.32
```

